// https://www.stevenfrady.com/tools/palette?p=[[0.2,0.51,0.52],[0.23,0.46,0.08],[0.72,0.8,0.73],[0.95,0.34,0.57]]
vec3 palette(float t){
  vec3 a=vec3(0.2,0.51,0.52);
  vec3 b=vec3(0.23,0.46,0.08);
  vec3 c=vec3(0.72,0.8,0.73);
  vec3 d=vec3(0.95,0.34,0.57);
  return a+b*cos(6.28318*(c*t+d));
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 r = vec3(uv, 1.0);
    vec4 o = vec4(0.0);
    float t = iTime;
    vec3 p;



    vec4 ColorOffset = vec4(p.x -.8, sin(p.z * 2.0)*5., (p.x -.65) ,1.);

    for (float i = 0.0, z = 0.0, d; i < 120.0; i++) {
        // Ray direction, modulated by time and camera
        p = z * normalize(vec3(uv, .9));

        p.z += -t*2.;

        // Rotating plane using a cos matrix
        vec4 angle = vec4(0, 11.0, 11.0, 1.0);
        vec4 a = z * 0.65  + angle*sin(p.z*.1+iTime*1.);
        p.xy *= mat2(cos(a.x), -sin(a.x), sin(a.x), cos(a.x));

        // Distance estimator
        z += d = length(cos(p + cos(p.yzx*1.1 + p.z * .05)*.3).xy) / 11.0;

        // Color accumulation using sin palette
        o.rgb +=(palette(p.z*.1)) / (d*30.);
    }

    o = pow(tanh(o*o /1e6),vec4(1./2.2));
    fragColor = vec4(o.rgb, 1.0)*2.;
}
